4. // Vmem — Specifications (spec phase)
5. //
6. // This file defines the abstract `VmemView` of a virtual address space and the
7. // spec-level vocabulary (address-partition predicates, permission model, and
8. // state-transition functions) that the `#[verus_spec]` contracts on `Vmem`'s
9. // exec methods are written against. See `view_design.md` for the rationale.
10. 
11. verus! {
12. 
13. //==================================================================================================
14. // External (opaque) dependency types
15. //
16. // These types live in lower-level, not-yet-verified crates (`sys`, `hal`,
17. // `mm::phys`). They are declared `external_body` so Verus treats them as opaque;
18. // the trust obligation is tracked here and is discharged when those modules are
19. // verified. Their projection into the abstract domain (below) is therefore
20. // `uninterp` — a mechanical consequence of the type being `external_body`.
21. //==================================================================================================
22. 
23. #[verifier::external_type_specification]
24. #[verifier::external_body]
25. pub struct ExVirtualAddress(VirtualAddress);
26. 
27. #[verifier::reject_recursive_types(T)]
28. #[verifier::external_type_specification]
29. #[verifier::external_body]
30. pub struct ExPageAligned<T: Address>(PageAligned<T>);
31. 
32. #[verifier::external_type_specification]
33. #[verifier::external_body]
34. pub struct ExAccessPermission(AccessPermission);
35. 
36. // --- Address / physical types (concrete) ---
37. 
38. #[verifier::external_type_specification]
39. #[verifier::external_body]
40. pub struct ExPhysicalAddress(PhysicalAddress);
41. 
42. #[verifier::external_type_specification]
43. #[verifier::external_body]
44. pub struct ExFrameAddress(FrameAddress);
45. 
46. #[verifier::external_type_specification]
47. #[verifier::external_body]
48. pub struct ExPageAddress(PageAddress);
49. 
50. #[verifier::external_type_specification]
51. #[verifier::external_body]
52. pub struct ExPageTableAddress(PageTableAddress);
53. 
54. #[verifier::external_type_specification]
55. #[verifier::external_body]
56. pub struct ExPageDirectoryAddress(PageDirectoryAddress);
57. 
58. #[verifier::reject_recursive_types(T)]
59. #[verifier::external_type_specification]
60. #[verifier::external_body]
61. pub struct ExPageTableAligned<T: Address>(PageTableAligned<T>);
62. 
63. // --- MMU paging types (generic over storage) ---
64. 
65. #[verifier::reject_recursive_types(T)]
66. #[verifier::external_type_specification]
67. #[verifier::external_body]
68. pub struct ExPageDirectory<T: core::ops::DerefMut<Target = [PteWord]>>(PageDirectory<T>);
