116. pub struct ExLinkedList<T, A: ::core::alloc::Allocator>(::alloc::collections::LinkedList<T, A>);
117. 
118. //==================================================================================================
119. // Abstract projections of the opaque address / permission types
120. //==================================================================================================
121. 
122. /// Projection of an address-like value to its raw byte address as a `nat`.
123. pub trait AddrNat {
124.     spec fn addr_nat(&self) -> nat;
125. }
126. 
127. impl AddrNat for VirtualAddress {
128.     uninterp spec fn addr_nat(&self) -> nat;
129. }
130. 
131. impl AddrNat for PageAligned<VirtualAddress> {
132.     uninterp spec fn addr_nat(&self) -> nat;
133. }
134. 
135. /// Projection of the concrete permission encoding to the abstract triple.
136. pub trait PermView {
137.     spec fn perms_view(&self) -> PagePerms;
138. }
139. 
140. impl PermView for AccessPermission {
141.     uninterp spec fn perms_view(&self) -> PagePerms;
142. }
143. 
144. //==================================================================================================
145. // Architectural constants (mirror `sys::config` / `arch::mem` layout values)
146. //==================================================================================================
147. 
148. /// Page size in bytes (`arch::mem::PAGE_SIZE`).
149. pub open spec fn page_size() -> nat {
150.     4096
151. }
152. 
153. /// First user-space byte address (`config::memory_layout::USER_BASE_RAW`).
154. pub open spec fn user_base() -> nat {
155.     0x4000_0000
156. }
157. 
158. /// One-past-last user-space byte address (`config::memory_layout::USER_END_RAW`).
159. pub open spec fn user_end() -> nat {
160.     0xf000_0000
161. }
162. 
163. /// Size of valid guest physical memory (`config::kernel::MEMORY_SIZE`).
164. pub open spec fn phys_mem_size() -> nat {
165.     ::config::kernel::MEMORY_SIZE as nat
166. }
167. 
168. //==================================================================================================
169. // Address-partition helpers (pure, total, instance-independent)
170. //==================================================================================================
171. 
172. pub open spec fn is_page_aligned(a: nat) -> bool {
173.     a % page_size() == 0
174. }
175. 
176. /// Page-aligned base of the page containing `a`.
177. pub open spec fn page_base(a: nat) -> nat {
178.     (a - (a % page_size())) as nat
179. }
180. 
181. /// Intra-page offset of `a`.
182. pub open spec fn page_offset(a: nat) -> nat {
183.     a % page_size()
184. }
185. 
186. /// Whether `a` lies in user space.
187. pub open spec fn spec_is_user_addr(a: nat) -> bool {
188.     user_base() <= a < user_end()
189. }
190. 
191. /// Whether `a` lies in kernel space (the total complement of user space).
192. pub open spec fn spec_is_kernel_addr(a: nat) -> bool {
193.     !spec_is_user_addr(a)
194. }
195. 
196. /// Whether `[start, start+size)` lies entirely in user space.
197. pub open spec fn spec_is_user_region(start: nat, size: nat) -> bool {
198.     &&& size > 0
199.     &&& user_base() <= start
200.     &&& start + size <= user_end()
201. }
202. 
203. /// Whether `[start, start+size)` lies entirely in kernel space (below the user
204. /// window). Matches the kernel half of the address partition.
205. pub open spec fn spec_is_kernel_region(start: nat, size: nat) -> bool {
206.     &&& size > 0
207.     &&& start + size <= user_base()
208. }
209. 
210. /// Whether `[start, start+size)` lies entirely within valid physical memory.
211. /// (`hal::platform::is_valid_physical_region`: rejects empty ranges.)
212. pub open spec fn spec_is_physical_region(start: nat, size: nat) -> bool {
213.     &&& size > 0
214.     &&& start + size <= phys_mem_size()
215. }
216. 
217. //==================================================================================================
218. // PagePerms — abstract access permissions
219. //==================================================================================================
220. 
221. /// Abstract access permissions of a mapped page.
222. pub struct PagePerms {
223.     pub read: bool,
224.     pub write: bool,
225.     pub execute: bool,
226. }
227. 
228. //==================================================================================================
229. // UserPageView / KernelPageView — single-mapping abstractions
230. //==================================================================================================
231. 
232. /// Abstract state of a single user-space mapping.
233. pub struct UserPageView {
234.     /// Physical base address of the backing user frame.
235.     pub frame: nat,
236.     /// Access permissions currently in effect for the page.
237.     pub perms: PagePerms,
238.     /// Whether the page is marked copy-on-write.
239.     pub cow: bool,
240. }
241. 
242. /// Abstract state of a single kernel-space mapping.
243. pub struct KernelPageView {
244.     /// Physical base address of the backing kernel page/frame.
245.     pub frame: nat,
246.     /// Access permissions currently in effect for the page.
247.     pub perms: PagePerms,
248. }
249. 
250. //==================================================================================================
251. // VmemView — abstract state of an entire address space
252. //==================================================================================================
253. 
254. /// Abstract view of a virtual memory space.
255. pub struct VmemView {
256.     /// User half: page-aligned user vaddr -> mapping.
257.     pub user: Map<nat, UserPageView>,
258.     /// Kernel half: page-aligned kernel vaddr -> mapping.
259.     pub kernel: Map<nat, KernelPageView>,
260.     /// Physical base address of the page directory (the value loaded into CR3).
261.     pub pgdir: nat,
262. }
263. 
264. impl VmemView {
265.     //==============================================================================================
266.     // Well-formedness invariant
267.     //==============================================================================================
268. 
269.     pub open spec fn inv(self) -> bool {
270.         // User keys are page-aligned user addresses.
271.         &&& forall|v: nat| #[trigger] self.user.contains_key(v)
272.                 ==> spec_is_user_addr(v) && is_page_aligned(v)
273.         // Kernel keys are page-aligned kernel addresses.
274.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v)
275.                 ==> spec_is_kernel_addr(v) && is_page_aligned(v)
276.         // User frames are valid, page-aligned, and CoW implies read-only.
277.         &&& forall|v: nat| #[trigger] self.user.contains_key(v) ==> {
278.                 &&& is_page_aligned(self.user[v].frame)
279.                 &&& spec_is_physical_region(self.user[v].frame, page_size())
280.                 &&& (self.user[v].cow ==> !self.user[v].perms.write)
281.             }
282.         // Kernel frames are valid and page-aligned.
283.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v) ==> {
284.                 &&& is_page_aligned(self.kernel[v].frame)
285.                 &&& spec_is_physical_region(self.kernel[v].frame, page_size())
286.             }
287.         // The page directory has a valid, page-aligned physical base.
288.         &&& is_page_aligned(self.pgdir)
289.         &&& spec_is_physical_region(self.pgdir, page_size())
290.     }
291. 
292.     //==============================================================================================
293.     // Observers
294.     //==============================================================================================
295. 
296.     /// Whether user virtual page `v` is mapped.
297.     pub open spec fn user_mapped(self, v: nat) -> bool {
298.         self.user.contains_key(v)
299.     }
300. 
301.     /// Whether kernel virtual page `v` is mapped.
302.     pub open spec fn kernel_mapped(self, v: nat) -> bool {
303.         self.kernel.contains_key(v)
304.     }
305. 
306.     /// Every CoW user page overlapping `[start, start+size)` is privatized.
307.     pub open spec fn region_cow_resolved(self, start: nat, size: nat) -> bool {
308.         forall|v: nat| #[trigger] self.user.contains_key(v)
309.             && page_base(start) <= v < start + size
310.             ==> !self.user[v].cow
311.     }
312. 
313.     //==============================================================================================
314.     // State transitions (mutators preserve unchanged fields via `..self`)
315.     //==============================================================================================
316. 
317.     pub open spec fn spec_map(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
318.         VmemView { user: self.user.insert(v, UserPageView { frame, perms, cow: false }), ..self }
319.     }
320. 
321.     pub open spec fn spec_unmap(self, v: nat) -> VmemView {
322.         VmemView { user: self.user.remove(v), ..self }
323.     }
324. 
325.     pub open spec fn spec_map_kpage(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
326.         VmemView { kernel: self.kernel.insert(v, KernelPageView { frame, perms }), ..self }
327.     }
328. 
329.     pub open spec fn spec_mark_cow(self, v: nat) -> VmemView {
330.         VmemView {
331.             user: self.user.insert(
332.                 v,
333.                 UserPageView {
334.                     perms: PagePerms { write: false, ..self.user[v].perms },
335.                     cow: true,
336.                     ..self.user[v]
337.                 },
338.             ),
339.             ..self
340.         }
341.     }
342. 
343.     pub open spec fn spec_unmark_cow(self, v: nat) -> VmemView {
344.         VmemView {
345.             user: self.user.insert(
346.                 v,
347.                 UserPageView {
348.                     perms: PagePerms { write: true, ..self.user[v].perms },
349.                     cow: false,
350.                     ..self.user[v]
351.                 },
352.             ),
353.             ..self
354.         }
355.     }
356. 
357.     /// `new_frame` is the freshly allocated private frame supplied existentially
358.     /// by the caller's ensures clause.
359.     pub open spec fn spec_resolve_cow(self, v: nat, new_frame: nat) -> VmemView {
360.         VmemView {
361.             user: self.user.insert(
362.                 v,
363.                 UserPageView {
364.                     frame: new_frame,
365.                     perms: PagePerms { write: true, ..self.user[v].perms },
366.                     cow: false,
367.                 },
368.             ),
369.             ..self
370.         }
371.     }
372. 
373.     pub open spec fn spec_uctrl(self, v: nat, perms: PagePerms) -> VmemView {
374.         VmemView {
375.             user: self.user.insert(v, UserPageView { perms, ..self.user[v] }),
376.             ..self
377.         }
378.     }
379. 
380.     pub open spec fn spec_kctrl(self, v: nat, perms: PagePerms) -> VmemView {
381.         VmemView {
382.             kernel: self.kernel.insert(v, KernelPageView { perms, ..self.kernel[v] }),
383.             ..self
384.         }
385.     }
386. }
387. 
388. //==================================================================================================
389. // Vmem — View and invariant
390. //==================================================================================================
391. 
392. impl View for Vmem {
393.     type V = VmemView;
394. 
395.     closed spec fn view(&self) -> VmemView {
396.         self.vmem_view@
397.     }
398. }
399. 
400. impl Vmem {
401.     /// Top-level invariant: the abstract view is well-formed.
402.     pub open spec fn inv(&self) -> bool {
403.         &&& self@.inv()
404.         &&& self.internal_inv()
405.     }
406. 
407.     /// Internal consistency between the concrete page-table representation and
408.     /// the abstract view. Refined during the proving phase.
409.     pub open spec fn internal_inv(&self) -> bool {
410.         true
411.     }
412. }
413. 
414. } // verus!
415.

